# VENDORED copy of measurements/orb_axes/axes_v3.py (generated by proto/sync_vendor.py)
"""Orb axes v3 (2026-11-05). Changes from v2:
- timing loses 'trigger' (trigger condition axis is the only trigger axis); trigger loses 'turn' (that is timing: repeating/delayed)
- range: self+one merged into 'single'
- lifetime: THREE reworded variants compared against the v2 wording (A: effect-in-game framing, B: with turn counts, S: ordinal score)
- bagfate2: reworded 'passive'
- unit / allegiance are asked in a second call only when role == summon (results of v2 reused), so they are not in this request."""
import sys
import axes, axes_v2
STATE, LANG_LINE = axes.STATE, axes.LANG_LINE
JUDGE = " Judge the effect when the orb is used in the game, not how eternal the named thing is in real life."
CHOICES = {k: axes_v2.CHOICES[k] for k in ("guard", "role", "material", "bagfate", "verb")}
CHOICES["timing"] = ("When would the effect of an orb with this name happen?",
  {"now":       "right away when used",
   "delayed":   "a few turns later, like a timer, a fuse, or a slow process",
   "repeating": "again and again every turn"})
CHOICES["trigger"] = ("Does the effect of an orb with this name wait for something to happen? If so, what sets it off?",
  {"none":     "no, it simply happens when used",
   "hit":      "when someone is hit or takes damage",
   "death":    "when someone dies or is destroyed",
   "orb":      "when another orb is used",
   "approach": "when an enemy comes near or steps on it"})
CHOICES["range"] = ("How far would the effect of an orb with this name reach?",
  {"single":  "one target, or only the user",
   "line":    "a line, a short path, or a few neighboring spots",
   "around":  "a ring or blast area around one point",
   "wide":    "everything on the whole field"})
CHOICES["lifetime_v2"] = axes_v2.CHOICES["lifetime"]                                   # baseline wording from v2
CHOICES["lifetime_A"] = ("If an orb with this name is used, how long would its effect last?" + JUDGE,
  {"instant": "it happens once and is over at once",
   "turns":   "a few turns, like a poison, a potion, a fire, or a spell",
   "stage":   "until the end of the current battle or level, like weather, a camp, a banner, or a siege",
   "run":     "for the whole journey across many battles, like a building, a tree, or a monument",
   "forever": "it becomes a permanent part of the world and never ends"})
CHOICES["lifetime_B"] = ("A game level lasts about 15 turns. If an orb with this name is used, how long would its effect last?" + JUDGE,
  {"instant": "0 turns: over at once",
   "turns":   "2 to 4 turns",
   "stage":   "about 15 turns: the rest of the level",
   "run":     "dozens of levels: the whole journey",
   "forever": "beyond the journey: permanent"})
CHOICES["bagfate2"] = ("What happens to an orb with this name after it is used?",
  {"used_up": "it is a one-time thing that gets used up",
   "returns": "it is a tool or ability that can be used again and again",
   "passive": "it is a lasting talent or charm that keeps working on its own while carried, and is never really used"})
MODS = axes_v2.MODS
SCORE_LIFE = ("For how long would the effect of an orb with this name last once it is used?" + JUDGE,
              ["over at once", "a few turns", "the rest of one battle", "the whole journey", "forever"])
def build_request(name, lang="ko"):
    q = {k: {"type": "choice", "instructions": i, "criteria": o} for k, (i, o) in CHOICES.items()}
    q["lifetime_S"] = {"type": "score", "instructions": SCORE_LIFE[0], "criteria": SCORE_LIFE[1]}
    for k, d in MODS.items():
        q[k] = {"type": "noul", "instructions": f"Is the thing named strongly associated with {d}?"}
    q["power"] = {"type": "score", "instructions": "How grand and powerful is the thing named, overall?", "criteria": axes.POWER}
    return {"model": "jev-latest", "state": STATE.format(name=name) + (LANG_LINE.format(lang=axes.LANGS[lang]) if lang != "en" else ""), "questions": q}
